ALTER TABLE "Account" ADD COLUMN "rating" INTEGER NOT NULL DEFAULT 1000, ADD COLUMN "battleGames" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "battleWins" INTEGER NOT NULL DEFAULT 0;
CREATE TABLE "BattleResult" ("matchId" TEXT PRIMARY KEY, "firstId" TEXT NOT NULL, "secondId" TEXT NOT NULL, "firstScore" INTEGER NOT NULL, "secondScore" INTEGER NOT NULL, "delta" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
